// Swaps photo placeholders for the real photos dropped into photos/ (see scripts/photos.mjs).
// media.json is generated by `npm run photos`; never edit it by hand.

import media from './media.json';
import type { Entry, ImageItem, Section, VideoItem } from './types';

interface MediaFile { src: string; alt: string | null; w: number; h: number; poster?: string }
const files = media as Record<string, MediaFile[]>;

/** Placeholders that share a slot are one gallery: they become one image per file in that folder. */
export function resolveImages(images: ImageItem[] | undefined): ImageItem[] | undefined {
    if (!images) return images;
    const out: ImageItem[] = [];
    const done = new Set<string>();
    images.forEach((img, i) => {
        const list = img.slot ? files[img.slot] : undefined;
        if (!img.slot || !list?.length) { out.push(img); return; }
        if (done.has(img.slot)) return;
        done.add(img.slot);
        const siblings = images.filter((x) => x.slot === img.slot);
        list.forEach((f, k) => {
            const ph = siblings[k] ?? siblings[0];
            const single = siblings.length === 1 && list.length === 1;
            out.push({
                src: f.src, width: f.w, height: f.h, slot: img.slot,
                // a single photo keeps its written description; gallery photos use their file names
                alt: single ? ph.alt : (f.alt ?? ph.alt.replace(/ \d+$/, ` ${k + 1}`)),
                caption: ph.caption && !ph.caption.includes('[TODO') ? ph.caption : undefined
            });
        });
        void i;
    });
    return out;
}

/** An MP4 with a drop folder becomes the converted file (and its poster frame) once it exists. */
const resolveVideo = (v: VideoItem): VideoItem => {
    const f = v.slot ? files[v.slot]?.[0] : undefined;
    return f ? { ...v, id: f.src, poster: f.poster, width: f.w, height: f.h } : v;
};

const walk = (s: Section & { tabs?: Section[] }) => {
    s.images = resolveImages(s.images);
    s.videos = s.videos?.map(resolveVideo);
    s.tabs?.forEach(walk);
};

/** Resolves one standalone section (and its tabs). */
export function resolveSection<T extends Section & { tabs?: Section[] }>(s: T): T {
    walk(s);
    return s;
}

/** Applied to each room's content when it loads. */
export function withMedia<T extends Record<string, Entry>>(content: T): T {
    Object.values(content).forEach(walk);
    return content;
}
